import{_ as e,o as a,c as l,af as s}from"./chunks/framework.BSym9njW.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/00-environment/xdna2-npu.md","filePath":"zh/00-environment/xdna2-npu.md","lastUpdated":1789547203000}'),n={name:"zh/00-environment/xdna2-npu.md"};function i(d,t,o,r,c,h){return a(),l("div",null,[...t[0]||(t[0]=[s(`<h2 id="ryzen-ai-xdna2-硬件对照" tabindex="-1">Ryzen AI XDNA2 硬件对照 <a class="header-anchor" href="#ryzen-ai-xdna2-硬件对照" aria-label="Permalink to &quot;Ryzen AI XDNA2 硬件对照&quot;">​</a></h2><p>本节说明 <strong>FastFlowLM / Lemonade NPU</strong> 路径需要的硬件。NPU 推理走 <strong>XDNA2</strong>，与 <a href="/hello-rocm/zh/00-environment/">ROCm GPU 栈</a> 相互独立：GPU 教程用 <code>gfx1151</code> 等 iGPU；NPU 教程用 <code>/dev/accel/accel0</code>。</p><blockquote><p>对照：<a href="https://lemonade-server.ai/flm_npu_linux.html" target="_blank" rel="noreferrer">Lemonade Linux + FLM</a> · <a href="https://fastflowlm.com/docs/install_lin/" target="_blank" rel="noreferrer">FastFlowLM Linux 安装</a></p></blockquote><hr><h3 id="_1-支持的处理器" tabindex="-1">1. 支持的处理器 <a class="header-anchor" href="#_1-支持的处理器" aria-label="Permalink to &quot;1. 支持的处理器&quot;">​</a></h3><p>FastFlowLM 在 Linux 上跑 NPU LLM <strong>只要 XDNA2</strong>。XDNA1 不能加载本教程的 NPU2 权重。</p><table tabindex="0"><thead><tr><th style="text-align:left;">系列</th><th style="text-align:left;">代号</th><th style="text-align:left;">NPU</th><th style="text-align:left;">本教程</th></tr></thead><tbody><tr><td style="text-align:left;">Ryzen AI Max 300</td><td style="text-align:left;">Strix Halo（如 MAX+ 395，gfx1151）</td><td style="text-align:left;">XDNA2</td><td style="text-align:left;"><strong>主推</strong>，实测示例机为 GMKtec EVO-X2</td></tr><tr><td style="text-align:left;">Ryzen AI 300</td><td style="text-align:left;">Kraken Point、Strix Point</td><td style="text-align:left;">XDNA2</td><td style="text-align:left;">支持；官方 Gemma 4 基准多用 Kraken</td></tr><tr><td style="text-align:left;">Ryzen AI 400</td><td style="text-align:left;">Gorgon Point</td><td style="text-align:left;">XDNA2</td><td style="text-align:left;">支持</td></tr><tr><td style="text-align:left;">Z2 Extreme</td><td style="text-align:left;">掌机</td><td style="text-align:left;">XDNA2</td><td style="text-align:left;">支持</td></tr><tr><td style="text-align:left;">Ryzen AI 7000 / 8000 / 200</td><td style="text-align:left;">Phoenix / Hawk Point 等</td><td style="text-align:left;"><strong>XDNA1</strong></td><td style="text-align:left;"><strong>不支持</strong> NPU LLM</td></tr></tbody></table><p>Strix Halo 的 iGPU 是 <strong>gfx1151</strong>。Lemonade 的 <code>llamacpp:rocm</code> / <code>llamacpp:vulkan</code> 走这块 iGPU，<strong>不占用</strong> <code>/dev/accel</code>。</p><hr><h3 id="_2-运行时栈" tabindex="-1">2. 运行时栈 <a class="header-anchor" href="#_2-运行时栈" aria-label="Permalink to &quot;2. 运行时栈&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">项</th><th style="text-align:left;">要求</th></tr></thead><tbody><tr><td style="text-align:left;">NPU 固件</td><td style="text-align:left;"><strong>1.1.0.0 或更高</strong>（本教程实测 1.1.2.65）</td></tr><tr><td style="text-align:left;">内核 + 驱动</td><td style="text-align:left;">内核 7.0+ 自带 <code>amdxdna</code>，或 Ubuntu 24.04 用 <code>amdxdna-dkms</code></td></tr><tr><td style="text-align:left;">用户态</td><td style="text-align:left;"><code>libxrt-npu2</code> + FastFlowLM（<code>flm</code>）</td></tr><tr><td style="text-align:left;">memlock</td><td style="text-align:left;"><code>ulimit -l</code> 为 <code>unlimited</code></td></tr><tr><td style="text-align:left;">设备节点</td><td style="text-align:left;"><code>/dev/accel/accel0</code>，用户在 <code>render</code>（建议同时加入 <code>video</code>）组</td></tr><tr><td style="text-align:left;">IOMMU</td><td style="text-align:left;">cmdline 同时有 <code>amd_iommu=on</code> 与 <code>iommu=pt</code></td></tr></tbody></table><hr><h3 id="_3-查本机" tabindex="-1">3. 查本机 <a class="header-anchor" href="#_3-查本机" aria-label="Permalink to &quot;3. 查本机&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lspci</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -nn</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> | </span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">grep</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -iE</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &#39;processing|display|npu&#39;</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ls</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -l</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> /dev/accel/accel0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Strix Halo 上 NPU PCI 常见为 <code>1022:17f0</code>。装好 <code>flm</code> 后再跑：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">unset</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ROCM_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> HIP_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> LD_LIBRARY_PATH</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">flm</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> validate</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>期望看到 NPU 设备、固件 <strong>1.1.x</strong>、memlock 为 infinity / unlimited。</p><hr><h3 id="_4-与-rocm-gpu-的关系" tabindex="-1">4. 与 ROCm GPU 的关系 <a class="header-anchor" href="#_4-与-rocm-gpu-的关系" aria-label="Permalink to &quot;4. 与 ROCm GPU 的关系&quot;">​</a></h3><ul><li><strong>可以共存</strong>：同一台 Ryzen AI MAX 上，ROCm 跑 GPU（vLLM / Ollama / llama.cpp），FastFlowLM 跑 NPU。</li><li><strong>不要混环境变量</strong>：<code>source /opt/rocm</code> 后再跑 <code>flm</code>，常见报错是 <code>No such device with index &#39;0&#39;</code>。每次跑 NPU 前先 <code>unset ROCM_PATH HIP_PATH LD_LIBRARY_PATH</code>。</li><li><strong>统一内存互斥</strong>：NPU 与大 GGUF 抢同一块系统内存。Gemma 4 E4B NPU 约 9 GiB；Qwen3.6-35B-A3B NPU 约 29 GiB。同时只常驻一路大模型。</li><li><strong>NPU 同时只能一路</strong>：Lemonade 若已经 <code>load</code> 了 FLM 模型，就不要再 <code>flm serve</code>。</li></ul><p>下一步：<a href="./fastflowlm">FastFlowLM 环境</a> · <a href="./lemonade">Lemonade 环境</a></p>`,21)])])}const m=e(n,[["render",i]]);export{g as __pageData,m as default};
